'use strict';
// 32 famílias originais × 3.200 instâncias com dados diferentes. Materializadas apenas sob demanda.
const JAVA_PRACTICE_VARIANTS=3200;
const JAVA_PRACTICE_FAMILIES=[];
function javaPracticeFamily(group,title,task,starter,answer,requires,hint){JAVA_PRACTICE_FAMILIES.push({group,title,task,starter,answer,requires,hint})}
const JP=(s)=>({a:s+17,b:s+2,c:s+1,d:s+3});
const JPI=n=>`int a = ${n.a}, b = ${n.b}, c = ${n.c};`;
const JPA=n=>`int[] valores = {${n.a}, ${n.b}, ${n.c}, ${n.a%13+1}};`;
const JPS=n=>`String texto = "Java${n.a}Lingo";`;
javaPracticeFamily('Fundamentos','Somar sem fixar a saída','Use variáveis e imprima Soma: seguido de a + b.',n=>`${JPI(n)}\n// Calcule a soma.`,n=>`Soma: ${n.a+n.b}`,/\ba\s*\+\s*b\b/,'Some as duas variáveis antes de imprimir.');
javaPracticeFamily('Fundamentos','Área do retângulo','Multiplique a por b e imprima Area: seguida do valor.',n=>`${JPI(n)}\n// Calcule área.`,n=>`Area: ${n.a*n.b}`,/\ba\s*\*\s*b\b/,'Área = largura × altura.');
javaPracticeFamily('Fundamentos','Quociente inteiro','Divida a por b com inteiros e imprima Quociente: seguido do valor.',n=>`${JPI(n)}\n// Divida inteiros.`,n=>`Quociente: ${Math.floor(n.a/n.b)}`,/\ba\s*\/\s*b\b/,'int / int descarta a parte decimal.');
javaPracticeFamily('Fundamentos','Resto da divisão','Use % para imprimir Resto: seguido de a % b.',n=>`${JPI(n)}\n// Calcule o resto.`,n=>`Resto: ${n.a%n.b}`,/\ba\s*%\s*b\b/,'O operador % devolve o resto.');
javaPracticeFamily('Fundamentos','Conversão para double','Converta antes da divisão e imprima Media: com duas casas usando printf.',n=>`${JPI(n)}\n// Média de a e b.`,n=>`Media: ${((n.a+n.b)/2).toFixed(2)}`,/\b(double|2\.0)\b[\s\S]*printf|printf[\s\S]*\b(double|2\.0)\b/,'Use (a + b) / 2.0 e System.out.printf(java.util.Locale.US, "Media: %.2f%n", ...).');
javaPracticeFamily('Condições','Maior de dois valores','Use if/else para imprimir Maior: seguido do maior entre a e b.',n=>`${JPI(n)}\n// Compare os dois.`,n=>`Maior: ${Math.max(n.a,n.b)}`,/\bif\s*\(/,'Comece supondo que a é maior e compare com b.');
javaPracticeFamily('Condições','Par ou ímpar','Use if para imprimir Par ou Impar de acordo com a.',n=>`${JPI(n)}\n// Teste o resto por 2.`,n=>n.a%2?'Impar':'Par',/\bif\s*\([\s\S]*%\s*2/,'a % 2 == 0 indica número par.');
javaPracticeFamily('Condições','Faixa de nota','Imprima Aprovado quando a % 11 >= 6 e Reprovar em outro caso.',n=>`${JPI(n)}\nint nota = a % 11;\n// Decida pela nota.`,n=>n.a%11>=6?'Aprovado':'Reprovar',/\bif\s*\(/,'Use nota >= 6.');
javaPracticeFamily('Condições','Maior de três','Use comparações condicionais para imprimir Maximo: do maior entre a, b e c.',n=>`${JPI(n)}\n// Compare os três.`,n=>`Maximo: ${Math.max(n.a,n.b,n.c)}`,/\bif\s*\(/,'Compare cada candidato com o maior atual.');
javaPracticeFamily('Laços','Soma de 1 até n','Use for e um acumulador para imprimir Soma: de 1 até a.',n=>`int a = ${n.a};\n// Some usando for.`,n=>`Soma: ${n.a*(n.a+1)/2}`,/\bfor\s*\(/,'Inicialize soma em 0 e repita de 1 até a.');
javaPracticeFamily('Laços','Tabuada completa','Use for para imprimir as três primeiras linhas da tabuada de b, no formato b x i = valor.',n=>`int numero = ${n.b};\n// Três linhas: i de 1 a 3.`,n=>[1,2,3].map(i=>`${n.b} x ${i} = ${n.b*i}`).join('\n'),/\bfor\s*\(/,'Use System.out.println(numero + " x " + i + " = " + numero * i).');
javaPracticeFamily('Laços','Contar pares','Use um laço para contar pares de 1 até a e imprima Pares: seguido da contagem.',n=>`int limite = ${n.a};\n// Conte os pares.`,n=>`Pares: ${Math.floor(n.a/2)}`,/\b(for|while)\s*\([\s\S]*%\s*2/,'Percorra 1..limite e incremente ao encontrar par.');
javaPracticeFamily('Laços','Fatorial limitado','Use for para calcular (a % 9 + 1)! e imprima Fatorial: seguido do resultado.',n=>`int a = ${n.a};\nint limite = a % 9 + 1;\n// Multiplique os fatores.`,n=>`Fatorial: ${Array.from({length:n.a%9+1},(_,i)=>i+1).reduce((a,b)=>a*b,1)}`,/\bfor\s*\(/,'Comece produto em 1.');
javaPracticeFamily('Laços','Potência por repetição','Calcule b elevado a 3 com um laço e um acumulador long; imprima Potencia: seguida do resultado.',n=>`long base = ${n.b};\n// Faça três multiplicações em um for.`,n=>`Potencia: ${n.b**3}`,/\bfor\s*\(/,'Comece long produto = 1 e faça produto *= base três vezes.');
javaPracticeFamily('Arrays','Somar um array','Percorra todos os valores e imprima Soma: seguida da soma.',n=>`${JPA(n)}\n// Use for-each.`,n=>`Soma: ${n.a+n.b+n.c+n.a%13+1}`,/\bfor\s*\(/,'Some cada valor ao acumulador.');
javaPracticeFamily('Arrays','Encontrar o máximo','Percorra o array e imprima Maximo: seguido do maior valor.',n=>`${JPA(n)}\n// Compare os elementos.`,n=>`Maximo: ${Math.max(n.a,n.b,n.c,n.a%13+1)}`,/\bfor\s*\([\s\S]*\bif\s*\(/,'Inicialize maior com valores[0].');
javaPracticeFamily('Arrays','Encontrar o mínimo','Percorra o array e imprima Minimo: seguido do menor valor.',n=>`${JPA(n)}\n// Compare os elementos.`,n=>`Minimo: ${Math.min(n.a,n.b,n.c,n.a%13+1)}`,/\bfor\s*\([\s\S]*\bif\s*\(/,'Inicialize menor com valores[0].');
javaPracticeFamily('Arrays','Contar acima da meta','Conte itens do array maiores que c e imprima Acima: seguida da contagem.',n=>`${JPA(n)}\nint meta = ${n.c};\n// Conte os itens.`,n=>`Acima: ${[n.a,n.b,n.c,n.a%13+1].filter(x=>x>n.c).length}`,/\bfor\s*\([\s\S]*\bif\s*\(/,'Percorra e teste valor > meta.');
javaPracticeFamily('Arrays','Ordenação simples','Ordene o array e imprima o menor, seguido do maior, separados por vírgula e espaço.',n=>`${JPA(n)}\n// Ordene com Arrays.sort.`,n=>`${Math.min(n.a,n.b,n.c,n.a%13+1)}, ${Math.max(n.a,n.b,n.c,n.a%13+1)}`,/Arrays\.sort\s*\(/,'Use java.util.Arrays.sort(valores) e índices 0 e length - 1.');
javaPracticeFamily('Strings','Comprimento do texto','Imprima Tamanho: seguido de texto.length().',n=>`${JPS(n)}\n// Conte os caracteres.`,n=>`Tamanho: ${`Java${n.a}Lingo`.length}`,/\.length\s*\(/,'String.length() conta caracteres.');
javaPracticeFamily('Strings','Texto em maiúsculas','Imprima texto com toUpperCase.',n=>`${JPS(n)}\n// Converta para letras maiúsculas.`,n=>`JAVA${n.a}LINGO`,/\.toUpperCase\s*\(/,'Use o método da String.');
javaPracticeFamily('Strings','Posição de Lingo','Imprima Indice: seguido da posição de Lingo no texto.',n=>`${JPS(n)}\n// Encontre a posição.`,n=>`Indice: ${`Java${n.a}`.length}`,/\.indexOf\s*\(/,'String.indexOf("Lingo") encontra a posição depois dos dígitos.');
javaPracticeFamily('Métodos','Dobro por método','Crie static int dobro(int n); chame com a e imprima Dobro: seguido do retorno.',n=>`int a = ${n.a};\n// Chame dobro(a) aqui.`,n=>`Dobro: ${2*n.a}`,/\bstatic\s+int\s+dobro\s*\(/,'Adicione static int dobro(int n) { return n * 2; } fora do main.');
javaPracticeFamily('Métodos','Recursão com caso base','Crie static int triangular(int n) recursivo e imprima T: para 1 + ... + (a % 20 + 1).',n=>`int a = ${n.a};\nint limite = a % 20 + 1;\n// Chame triangular(limite).`,n=>`T: ${(n.a%20+1)*(n.a%20+2)/2}`,/triangular\s*\([\s\S]*\breturn\b/,'Caso base n <= 0 devolve 0; em outro caso, n + triangular(n - 1).');
javaPracticeFamily('POO','Record de estudante','Crie record Estudante(int id) e imprima ID: seguido de id().',n=>`int numero = ${n.a};\n// Crie Estudante(numero) e leia id().`,n=>`ID: ${n.a}`,/record\s+Estudante[\s\S]*\.id\s*\(/,'Defina o record fora de Main.');
javaPracticeFamily('Coleções','Set de valores distintos','Adicione os quatro valores em HashSet<Integer> e imprima Unicos: seguido do tamanho.',n=>`${JPA(n)}\n// Monte um HashSet.`,n=>`Unicos: ${new Set([n.a,n.b,n.c,n.a%13+1]).size}`,/HashSet[\s\S]*\.add\s*\(/,'Use java.util.HashSet<Integer>, add e size.');
javaPracticeFamily('Coleções','Mapa de preços','Crie HashMap<String,Integer>, associe a chave "item" ao valor a e imprima Preco: seguido de get("item").',n=>`int a = ${n.a};\n// Crie um mapa e consulte a chave.`,n=>`Preco: ${n.a}`,/HashMap[\s\S]*\.put\s*\([\s\S]*\.get\s*\(/,'Use java.util.HashMap<String,Integer>.');
javaPracticeFamily('Coleções','Stream de pares','Use Arrays.stream(valores), filter e sum para imprimir Soma dos pares: seguida do resultado.',n=>`${JPA(n)}\n// Some pares em um Stream.`,n=>`Soma dos pares: ${[n.a,n.b,n.c,n.a%13+1].filter(x=>x%2===0).reduce((a,b)=>a+b,0)}`,/Arrays\.stream[\s\S]*\.filter[\s\S]*\.sum\s*\(/,'Use filter(x -> x % 2 == 0).sum().');
javaPracticeFamily('APIs Java','Raiz quadrada inteira','Use Math.sqrt e (int) para imprimir Raiz: da parte inteira da raiz de a.',n=>`int a = ${n.a};\n// Use Math.sqrt.`,n=>`Raiz: ${Math.floor(Math.sqrt(n.a))}`,/Math\.sqrt\s*\(/,'Converta (int) Math.sqrt(a).');
javaPracticeFamily('APIs Java','Arredondamento para cima','Calcule (double) a / b e imprima Teto: com Math.ceil e conversão para int.',n=>`${JPI(n)}\n// Arredonde para cima.`,n=>`Teto: ${Math.ceil(n.a/n.b)}`,/Math\.ceil\s*\(/,'Use (int) Math.ceil((double)a / b).');
javaPracticeFamily('APIs Java','Data depois de dias','Some c dias a 2026-01-01 com LocalDate.plusDays; imprima Data: seguida de ISO.',n=>`int dias = ${n.c};\n// Use LocalDate.parse e plusDays.`,n=>`Data: ${new Date(Date.UTC(2026,0,1+n.c)).toISOString().slice(0,10)}`,/LocalDate[\s\S]*\.plusDays\s*\(/,'Use java.time.LocalDate.parse("2026-01-01").plusDays(dias).');
javaPracticeFamily('APIs Java','BigDecimal sem erro binário','Some a.10 e b.20 como strings com BigDecimal; imprima Total: com duas casas.',n=>`String x = "${n.a}.10", y = "${n.b}.20";\n// Use BigDecimal(String) e add.`,n=>`Total: ${n.a+n.b}.30`,/BigDecimal[\s\S]*\.add\s*\(/,'Use new java.math.BigDecimal(x).add(new java.math.BigDecimal(y)).');
if(JAVA_PRACTICE_FAMILIES.length*JAVA_PRACTICE_VARIANTS<=100000)throw Error('Catálogo prático incompleto');
function javaPractice(index,variant){
  const f=JAVA_PRACTICE_FAMILIES[index],n=JP(variant),body=f.starter(n);
  return {...f,index,variant,id:`${index}:${variant}`,expected:f.answer(n),code:`public class Main {\n  public static void main(String[] args) throws Exception {\n    ${body.split('\n').join('\n    ')}\n  }\n}`};
}
